1	-- Fix: branch page_enter do trigger não acumulava top_pages.
2	-- Bug: jsonb_agg sobre array vazio retorna NULL, e `NULL || obj = NULL`,
3	-- então top_pages permanecia vazio para sempre. Separamos found/not-found
4	-- e usamos COALESCE em todos os pontos onde jsonb_agg pode retornar NULL.
5	
6	CREATE OR REPLACE FUNCTION fn_update_behavioral_profile()
7	RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
8	DECLARE
9	    v_hour int4;
10	    v_peak jsonb;
11	    v_feat jsonb;
12	    v_feat_id text;
13	    v_feat_count int4;
14	    v_pages jsonb;
15	    v_page_found bool := false;
16	    v_dwell_ms int8;
17	    v_page text;
18	    v_from text;
19	    v_to text;
20	BEGIN
21	    v_hour := EXTRACT(HOUR FROM NEW.created_at)::int4;
22	    v_page := NEW.page;
23	
24	    INSERT INTO mia_user_patterns(user_id)
25	        VALUES(NEW.user_id)
26	        ON CONFLICT (user_id) DO NOTHING;
27	
28	    SELECT COALESCE(peak_hours, '{}') INTO v_peak FROM mia_user_patterns WHERE user_id = NEW.user_id;
29	    v_peak := jsonb_set(v_peak, ARRAY[v_hour::text], to_jsonb(COALESCE((v_peak ->> v_hour::text)::int4, 0) + 1));
30	
31	    -- feature_use
32	    IF NEW.event_type = 'feature_use' THEN
33	        v_feat_id := NEW.properties->>'feature_id';
34	        IF v_feat_id IS NOT NULL THEN
35	            SELECT COALESCE(feature_usage_map, '{}') INTO v_feat FROM mia_user_patterns WHERE user_id = NEW.user_id;
36	            v_feat_count := COALESCE((v_feat ->> v_feat_id)::int4, 0) + 1;
37	            v_feat := jsonb_set(v_feat, ARRAY[v_feat_id], to_jsonb(v_feat_count));
38	            UPDATE mia_user_patterns
39	                SET feature_usage_map = v_feat, peak_hours = v_peak, behavioral_updated_at = now()
40	                WHERE user_id = NEW.user_id;
41	            RETURN NEW;
42	        END IF;
43	    END IF;
44	
45	    -- page_exit: avg_dwell_ms + nav_graph
46	    IF NEW.event_type = 'page_exit' THEN
47	        v_dwell_ms := (NEW.properties->>'dwell_ms')::int8;
48	        v_from := v_page;
49	        v_to := NEW.properties->>'next_page';
50	
51	        IF v_dwell_ms IS NOT NULL AND v_dwell_ms > 0 THEN
52	            DECLARE
53	                v_dwell_map jsonb;
54	                v_old_avg int8;
55	                v_old_count int4;
56	                v_new_avg int8;
57	            BEGIN
58	                SELECT COALESCE(avg_dwell_ms, '{}') INTO v_dwell_map FROM mia_user_patterns WHERE user_id = NEW.user_id;
59	                v_old_avg := COALESCE((v_dwell_map -> v_page ->> 'avg')::int8, 0);
60	                v_old_count := COALESCE((v_dwell_map -> v_page ->> 'count')::int4, 0);
61	                v_new_avg := ((v_old_avg * v_old_count) + v_dwell_ms) / (v_old_count + 1);
62	                v_dwell_map := jsonb_set(v_dwell_map, ARRAY[v_page],
63	                    jsonb_build_object('avg', v_new_avg, 'count', v_old_count + 1));
64	                UPDATE mia_user_patterns
65	                    SET avg_dwell_ms = v_dwell_map, peak_hours = v_peak, behavioral_updated_at = now()
66	                    WHERE user_id = NEW.user_id;
67	            END;
68	        END IF;
69	
70	        IF v_from IS NOT NULL AND v_to IS NOT NULL AND v_from != v_to THEN
71	            INSERT INTO user_nav_graph(user_id, from_page, to_page, weight, last_seen_at)
72	                VALUES(NEW.user_id, v_from, v_to, 1, now())
73	                ON CONFLICT (user_id, from_page, to_page)
74	                DO UPDATE SET weight = user_nav_graph.weight + 1, last_seen_at = now();
75	        END IF;
76	
77	        RETURN NEW;
78	    END IF;
79	
80	    -- mia_suggestion_acted
81	    IF NEW.event_type = 'mia_suggestion_acted' THEN
82	        UPDATE mia_user_patterns
83	            SET mia_suggestion_act_rate = (
84	                COALESCE(mia_suggestion_act_rate, 0) * 0.8 +
85	                CASE WHEN (NEW.properties->>'acted')::bool THEN 0.2 ELSE 0 END
86	            ),
87	            peak_hours = v_peak, behavioral_updated_at = now()
88	            WHERE user_id = NEW.user_id;
89	        RETURN NEW;
90	    END IF;
91	
92	    -- page_enter: top_pages (FIX — separa found/not-found, COALESCE em todo agg)
93	    IF NEW.event_type = 'page_enter' THEN
94	        SELECT COALESCE(top_pages, '[]'::jsonb) INTO v_pages FROM mia_user_patterns WHERE user_id = NEW.user_id;
95	
96	        v_page_found := EXISTS(
97	            SELECT 1 FROM jsonb_array_elements(v_pages) elem WHERE elem->>'page' = v_page
98	        );
99	
100	        IF v_page_found THEN
101	            -- incrementa count da página existente
102	            v_pages := COALESCE((
103	                SELECT jsonb_agg(
104	                    CASE WHEN elem->>'page' = v_page
105	                        THEN jsonb_set(elem, '{count}', to_jsonb((elem->>'count')::int4 + 1))
106	                        ELSE elem END
107	                ) FROM jsonb_array_elements(v_pages) elem
108	            ), '[]'::jsonb);
109	        ELSE
110	            -- nova página — append seguro (v_pages nunca é NULL aqui)
111	            v_pages := v_pages || jsonb_build_object('page', v_page, 'count', 1);
112	        END IF;
113	
114	        -- mantém top-20 por count (ORDER BY antes do LIMIT)
115	        v_pages := COALESCE((
116	            SELECT jsonb_agg(elem ORDER BY (elem->>'count')::int4 DESC)
117	            FROM (
118	                SELECT elem FROM jsonb_array_elements(v_pages) elem
119	                ORDER BY (elem->>'count')::int4 DESC LIMIT 20
120	            ) sub
121	        ), v_pages);
122	
123	        UPDATE mia_user_patterns
124	            SET top_pages = COALESCE(v_pages, '[]'::jsonb), peak_hours = v_peak, behavioral_updated_at = now()
125	            WHERE user_id = NEW.user_id;
126	        RETURN NEW;
127	    END IF;
128	
129	    -- fallback: só peak_hours
130	    UPDATE mia_user_patterns
131	        SET peak_hours = v_peak, behavioral_updated_at = now()
132	        WHERE user_id = NEW.user_id;
133	
134	    RETURN NEW;
135	END;
136	$$;
